css:
.vo-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.vo-stage canvas { touch-action: none; cursor: grab; }
.vo-stage canvas.holding { cursor: grabbing; }
.vo-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 3px; font-size: 16px; }
.vo-list li { display: grid; grid-template-columns: 4.2em 1fr; gap: 6px; padding: 3px 8px; border-radius: 8px; color: #9aa2ae; border-left: 4px solid #d5dae2; transition: background .3s, color .3s; }
.vo-list li b { font-weight: 800; }
.vo-list li.harm.on { color: #1d2433; background: #fde4dc; border-left-color: #d24b2a; }
.vo-list li.good.on { color: #1d2433; background: #e2f3d6; border-left-color: #4f9a2f; }
.vo-out { margin: 0; font-size: 18px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 6px 12px; min-height: 3.2em; }

